const D = { density:.5, scale:1, energy:.6, speed:1, hue:28, x:.5, y:.5, style:'extruded', seed:0, act:'turn', word:'LIVE' };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };
const TAU=6.28318530718, u=Math.min(width,height);
const fr = i => { const q=Math.sin(i*127.1 + P.seed*311.7)*43758.5453; return q-Math.floor(q); };
const style=P.style, H=((P.hue%360)+360)%360;
let word=((''+P.word).toUpperCase()).slice(0,14); if(!/[^ ]/.test(word)) word='LIVE';
if (S.lastBeat==null || K.beat<S.lastBeat) S.lastBeat=K.beat; S.lastBeat=K.beat;

// ---- background cache ----
const bgKey=width+'x'+height+'|'+style+'|'+P.seed+'|'+(H|0);
if (!S.bg || S.bgKey!==bgKey){
  const g=S.bg||(S.bg=createGraphics(width,height));
  g.pixelDensity(1); g.colorMode(HSB,360,100,100,100); g.clear();
  const base = (style==='xray')?12:8;
  g.background((H+210)%360, 38, base);
  g.noStroke();
  for (let r=14;r>0;r--){ g.fill((H+30)%360, 30, base+r*0.7, 4); g.ellipse(width*0.5, height*0.46, u*0.15*r, u*0.15*r); }
  for (let i=0;i<700;i++){ const x=fr(i*5)*width, y=fr(i*5+2)*height; g.fill(0,0,90,fr(i*7)*8); g.rect(x,y,1,1); }
  // floor horizon line for depth grounding
  g.stroke((H+30)%360,25,26,40); g.strokeWeight(Math.max(1,u*0.004));
  g.line(0,height*0.72,width,height*0.72);
  S.bgKey=bgKey;
}
image(S.bg,0,0);

// ---- rotation / dramaturgy ----
const sp=P.speed, act=P.act;
let yaw;
if (act==='spin'){ yaw=(K.t*0.6*sp)%TAU; }
else if (act==='pump'){ yaw=(0.9*Math.sin(K.t*0.5*sp))*0.5 + K.pulse*0.7*Math.sin(K.t*1.7); }
else { yaw=1.05*Math.sin(K.t*0.35*sp) + 0.12*Math.sin(K.t*0.83); } // turn: readable oscillation
const foresh=Math.cos(yaw);
const dir=Math.sin(yaw);
const tilt=0.06*Math.sin(K.t*0.21) + (A.lowmid||0)*0.05;
const bob=(0.02*Math.sin(K.t*0.5) + K.swell*0.02) * u;

// ---- depth extrusion ----
const nSlices=Math.max(3, Math.round(4 + P.density*40));
const ts=u*0.34*P.scale;
const depth=ts*0.5*(0.5+P.energy);
const cxp=P.x*width, cyp=P.y*height + bob;
const treb=A.treble||0, bass=A.bass||0;

textAlign(CENTER,CENTER); textStyle(BOLD); textSize(ts);

// per-letter layout (centered) for jitter on the front face
const gap=ts*0.04;
let total=0;
for (let i=0;i<word.length;i++){ const c=word[i]; total += ((c===' ')?ts*0.5:textWidth(c)) + gap; }
total-=gap;

// extrusion body: whole string, back -> front
push();
translate(cxp, cyp);
rotate(tilt);
scale(foresh<0?Math.max(0.06,Math.abs(foresh)):Math.max(0.06,foresh), 1);
const backSat=(style==='chrome'||style==='neon')?18:46;
for (let s=nSlices; s>=1; s--){
  const f=s/nSlices;                 // 1 at back -> ~0 at front
  const ox=dir*depth*f;
  const oy=depth*f*0.42;             // camera-down depth cue
  if (style==='wireframe'){
    if (s===nSlices){ noFill(); stroke(H,50,80,55); strokeWeight(Math.max(1,ts*0.012)); text(word,ox,oy); }
    continue;
  }
  if (style==='xray'){
    blendMode(ADD); noStroke();
    fill(H, 60, 34, 7+ (1-f)*6); text(word,ox,oy); blendMode(BLEND); continue;
  }
  const b= 16 + (1-f)*44;            // dark back -> lit front body
  noStroke(); fill((H+ (1-f)*10)%360, backSat, b, 100); text(word,ox,oy);
}
pop();

// ---- front face (per-letter, jittered) ----
push();
translate(cxp, cyp);
rotate(tilt);
scale(foresh<0?-Math.max(0.06,Math.abs(foresh)):Math.max(0.06,foresh), 1); // mirror when turned past 90
let lx=-total/2;
for (let i=0;i<word.length;i++){
  const c=word[i]; const w=(c===' ')?ts*0.5:textWidth(c);
  const gx=lx+w/2, gy=0;
  const jx=(fr(i*13+Math.floor(K.t*22))-0.5)*ts*0.10*(treb*1.6+0.05);
  const jy=(fr(i*13+7+Math.floor(K.t*22))-0.5)*ts*0.10*(treb*1.6+0.05) + K.pulse*ts*0.02*bass;
  if (c!==' '){
    if (style==='wireframe'){
      noFill(); stroke(H,70,100,90); strokeWeight(Math.max(1.2,ts*0.016)); text(c,gx+jx,gy+jy);
      stroke(H,40,60,40); strokeWeight(1); text(c,gx+jx+ts*0.02,gy+jy+ts*0.02);
    } else if (style==='chrome'){
      // iridescent metallic front: vertical hue sweep bands + specular streak
      noStroke();
      for (let b2=0;b2<5;b2++){ const fy=b2/5; const hh=(H + b2*26 + K.t*22)%360;
        drawingContext.save();
        drawingContext.beginPath();
        drawingContext.rect(gx+jx-w, gy+jy-ts*0.6 + fy*ts*1.2, w*2, ts*1.2/5);
        drawingContext.clip();
        fill(hh, 42, 92, 100); text(c,gx+jx,gy+jy);
        drawingContext.restore(); }
      fill(0,0,100, 26+treb*40); text(c,gx+jx-ts*0.02,gy+jy-ts*0.04); // specular hilite
    } else if (style==='neon'){
      drawingContext.shadowColor=color(H,80,100,90).toString();
      drawingContext.shadowBlur=u*0.02*(0.6+P.energy)*(0.8+bass*0.6);
      noFill(); stroke(H,72,100,92); strokeWeight(Math.max(1.5,ts*0.02)); text(c,gx+jx,gy+jy);
      drawingContext.shadowBlur=u*0.008; stroke((H+10)%360,30,100,95); strokeWeight(Math.max(1,ts*0.008)); text(c,gx+jx,gy+jy);
      drawingContext.shadowBlur=0; noStroke();
    } else if (style==='halftone'){
      noStroke();
      const step=Math.max(4,ts*0.055);
      for (let sx=-w*0.6; sx<w*0.6; sx+=step){
        drawingContext.save(); drawingContext.beginPath();
        drawingContext.rect(gx+jx+sx, gy+jy-ts*0.6, step, ts*1.2); drawingContext.clip();
        const dd=0.5+0.5*Math.sin(sx*0.4+K.t*3);
        fill((H+ (sx>0?320:190))%360, 78, 92, 60+dd*30); text(c,gx+jx,gy+jy);
        drawingContext.restore();
      }
    } else { // extruded: bright modeled front face
      noStroke(); fill((H+8)%360, 40, 96, 100); text(c,gx+jx,gy+jy);
      fill(0,0,100, 22+treb*30); text(c,gx+jx-ts*0.015,gy+jy-ts*0.03); // top hilite
    }
  }
  lx += w+gap;
}
pop();
drawingContext.shadowBlur=0; blendMode(BLEND);
